describe('File Upload Virus Scan Status', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Adjust the URL to your application's upload page
    });

    it('should display virus scan status for a successfully uploaded file', () => {
        const fileName = 'test-file.pdf'; // Replace with an actual file name
        cy.fixture(fileName).then(fileContent => {
            cy.get('input[type="file"]').attachFile(fileName);
            cy.get('button[type="submit"]').click();
            cy.wait(2000); // Wait for the upload and scan to complete
            cy.get('.scan-status').should('contain', 'Scan completed: No threats detected');
        });
    });

    it('should display an error message for a file with detected threats', () => {
        const maliciousFileName = 'malicious-file.exe'; // Replace with an actual malicious file name
        cy.fixture(maliciousFileName).then(fileContent => {
            cy.get('input[type="file"]').attachFile(maliciousFileName);
            cy.get('button[type="submit"]').click();
            cy.wait(2000); // Wait for the upload and scan to complete
            cy.get('.scan-status').should('contain', 'Scan completed: Threats detected');
        });
    });
});
